{
  "title": "tBreg Tumor Dynamics Game",
  "perWatchSecond": 0.9,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "tBregs drive tumor to capacity despite NK killing",
      "goal": "Show that increasing NK killing does not prevent tumor from reaching its carrying capacity.",
      "control": {
        "parameter": "c",
        "label": "NK killing rate",
        "lowEnd": "1e-10",
        "highEnd": "5e-10"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Double the NK killing rate",
        "parameter": "c",
        "value": 4e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "first-reach",
        "at": 900000000,
        "time": 70,
        "relation": "higher",
        "by": 10
      },
      "effect": "Doubling NK killing delays tumor reaching 90 % of its carrying capacity by about 10 days.",
      "prediction": {
        "prompt": "Will the tumor still reach near‑capacity when NK killing is doubled?",
        "claimed": "Yes, it will still reach capacity",
        "other": "but later"
      },
      "passage": {
        "title": "Headline result",
        "quote": "a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "NK killing rate will be the control for the next level, focusing on tBreg influence without them."
    },
    {
      "kind": "background",
      "finding": 2,
      "title": "Tumor control without tBregs",
      "goal": "Demonstrate that removing tBregs keeps the tumor far below its carrying capacity when NK killing is unchanged.",
      "control": {
        "parameter": "mT",
        "label": "Tumour‑induced tBreg growth",
        "lowEnd": "1e-15",
        "highEnd": "1e-14"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Start with no tBregs",
        "parameter": "b0",
        "value": 0
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 0.8
      },
      "effect": "Removing tBregs lowers the tumor peak to about 20 % of the original.",
      "prediction": {
        "prompt": "If tBregs are absent, will the tumor still grow to its maximum size?",
        "claimed": "No, the peak will be much lower",
        "other": "NK killing remains the same"
      },
      "passage": {
        "title": "No tBregs result",
        "quote": "when tBregs do not exist in the body, the only way for the breast tumour to reach its carrying capacity is for the rate of NK-induced breast cancer cell death to be tending to 0"
      },
      "carryForward": "Now we examine how changing NK killing rate affects outcomes when tBregs are present."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "NK killing threshold creates bifurcation",
      "goal": "Show that raising NK killing above its critical threshold suppresses tumor growth dramatically.",
      "control": {
        "parameter": "thetaN",
        "label": "NK death rate",
        "lowEnd": "0.01",
        "highEnd": "0.1"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "Increase NK killing rate above its threshold",
        "parameter": "c",
        "value": 3.5e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "peak",
        "at": null,
        "time": 70,
        "relation": "lower",
        "by": 0.9
      },
      "effect": "Raising NK killing above the threshold reduces the tumor peak by about 90 %.",
      "prediction": {
        "prompt": "Will raising NK killing above its critical threshold suppress the tumor?",
        "claimed": "Yes, the peak will be much lower",
        "other": "tumor may be cleared"
      },
      "passage": {
        "title": "Bifurcation result",
        "quote": "System [reducedModel] experiences a transcritical bifurcation at the equilibrium point E1 ≡ E2 as the parameter c varies through c1."
      },
      "carryForward": "We have seen how NK killing and tBregs shape tumor dynamics."
    }
  ],
  "limits": [
    "All simulations run for 70 days."
  ]
}
